content:
260                      }
   261                  }
   262
   263                  if (log_ctx != NULL) {
   264                      if (byte_index < last_byte) {
   265                          log_ctx->fn(log_ctx->ctx, ",");
   266                      }
   267                      log_ctx->fn(log_ctx->ctx, "\n");
   268                  }
   269              }
   270
   271              if (log_ctx != NULL) {
   272                  ptls_asn1_print_indent(level, log_ctx);
   273                  log_ctx->fn(log_ctx->ctx, "}");
   274              }
   275          } else {
   276              ptls_asn1_dump_content(bytes, last_byte, byte_index, log_ctx);
   277              byte_index = last_byte;
   278          }
   279      }
   280
   281      return byte_index;
   282  }
   283
   284  int ptls_asn1_validation(const uint8_t *bytes, size_t length, ptls_minicrypto_log_ctx_t *log_ctx)
   285  {
   286      int decode_error = 0;
   287      size_t decoded = ptls_asn1_validation_recursive(bytes, length, &decode_error, 0, log_ctx);
   288
   289      if (decode_error == 0 && decoded < length) {
   290          decode_error = PTLS_ERROR_BER_ELEMENT_TOO_SHORT;
   291          if (log_ctx != NULL) {
   292              log_ctx->fn(log_ctx->ctx, "Type too short, %d bytes only out of %d\n", (int)decoded, (int)length);
   293          }
   294      }
   295
   296      return decode_error;
   297  }
